def htr_versioned_hashes_subtree(versioned_hashes: StatelessInputSlice, start: int, count: htr_leaf_count, depth: htr_depth) -> hash:
    if ((count) == (0)):
        return Bytes32(ssz_zero_hash(depth))
    else:
        if ((depth) == (0)):
            if ((count) == (1)):
                return Bytes32(htr_chunk(versioned_hashes, start))
            else:
                return Bytes32(fatal_error(FatalError.WitnessDeficient))
        else:
            child_depth = (int(depth) - 1)
            half = htr_leaf_capacity(child_depth)
            if (int(count) < int(half)):
                left_count = count
            else:
                left_count = half
            if (int(count) < int(half)):
                right_count = 0
            else:
                right_count = (int(count) - int(half))
            left_root = htr_versioned_hashes_subtree(versioned_hashes, start, left_count, child_depth)
            right_root = htr_versioned_hashes_subtree(versioned_hashes, (int(start) + int(half)), right_count, child_depth)
            return Bytes32(_host_sha256_pair(left_root, right_root))

def htr_versioned_hashes(versioned_hashes: StatelessInputSlice) -> hash:
    items = ssz_bounded_fixed_list_ref(versioned_hashes, WORD_BYTE_LENGTH, (1 << 12))
    count = items.count
    root = htr_versioned_hashes_subtree(versioned_hashes, 0, count, 12)
    return Bytes32(mix_in_length(root, items.count))

def htr_deposit(deposit: StatelessInputSliceFields) -> hash:
    pubkey = htr_ssz_bytevector(deposit, HTR_DEPOSIT_PUBKEY, HTR_DEPOSIT_PUBKEY_LENGTH)
    withdrawal_credentials = htr_ssz_bytes32(deposit, HTR_DEPOSIT_WITHDRAWAL_CREDENTIALS)
    amount = htr_ssz_uint(deposit, HTR_DEPOSIT_AMOUNT)
    signature = htr_ssz_bytevector(deposit, HTR_DEPOSIT_SIGNATURE, HTR_DEPOSIT_SIGNATURE_LENGTH)
    index = htr_ssz_uint(deposit, HTR_DEPOSIT_INDEX)
    return Bytes32(merkleize([pubkey, withdrawal_credentials, amount, signature, index], 3))

def htr_withdrawal_request(request: StatelessInputSliceFields) -> hash:
    source_address = htr_ssz_addr(request, HTR_REQUEST_SOURCE_ADDRESS)
    source_pubkey = htr_ssz_bytevector(request, HTR_REQUEST_SOURCE_PUBKEY, HTR_REQUEST_PUBKEY_LENGTH)
    amount = htr_ssz_uint(request, HTR_WITHDRAWAL_REQUEST_AMOUNT)
    return Bytes32(merkleize([source_address, source_pubkey, amount], 2))

def htr_consolidation_request(request: StatelessInputSliceFields) -> hash:
    source_address = htr_ssz_addr(request, HTR_REQUEST_SOURCE_ADDRESS)
    source_pubkey = htr_ssz_bytevector(request, HTR_REQUEST_SOURCE_PUBKEY, HTR_REQUEST_PUBKEY_LENGTH)
    target_pubkey = htr_ssz_bytevector(request, HTR_CONSOLIDATION_REQUEST_TARGET_PUBKEY, HTR_REQUEST_PUBKEY_LENGTH)
    return Bytes32(merkleize([source_address, source_pubkey, target_pubkey], 2))

def htr_builder_deposit_request(request: StatelessInputSliceFields) -> hash:
    pubkey = htr_ssz_bytevector(request, HTR_BUILDER_DEPOSIT_PUBKEY, HTR_REQUEST_PUBKEY_LENGTH)
    withdrawal_credentials = htr_ssz_bytes32(request, HTR_BUILDER_DEPOSIT_WITHDRAWAL_CREDENTIALS)
    amount = htr_ssz_uint(request, HTR_BUILDER_DEPOSIT_AMOUNT)
    signature = htr_ssz_bytevector(request, HTR_BUILDER_DEPOSIT_SIGNATURE, HTR_DEPOSIT_SIGNATURE_LENGTH)
    return Bytes32(merkleize([pubkey, withdrawal_credentials, amount, signature], 2))

def htr_builder_exit_request(request: StatelessInputSliceFields) -> hash:
    source_address = htr_ssz_addr(request, HTR_BUILDER_EXIT_SOURCE_ADDRESS)
    pubkey = htr_ssz_bytevector(request, HTR_BUILDER_EXIT_PUBKEY, HTR_REQUEST_PUBKEY_LENGTH)
    return Bytes32(merkleize([source_address, pubkey], 1))

class HtrRequestKind(UintEnum):
    HtrDeposit = Uint(0)
    HtrWithdrawalRequest = Uint(1)
    HtrConsolidationRequest = Uint(2)
    HtrBuilderDepositRequest = Uint(3)
    HtrBuilderExitRequest = Uint(4)

def htr_request_leaf(requests: StatelessInputSlice, index: int, kind: HtrRequestKind) -> hash:
    match kind:
        case HtrRequestKind.HtrDeposit:
            offset = (int(index) * int(HTR_DEPOSIT_LENGTH))
            if (int((int(offset) + int(HTR_DEPOSIT_LENGTH))) <= int(requests.len)):
                deposit = stateless_input_sub_slice(requests, offset, HTR_DEPOSIT_LENGTH)
                return Bytes32(htr_deposit(deposit))
            else:
                return Bytes32(fatal_error(FatalError.InvalidConfig))
        case HtrRequestKind.HtrWithdrawalRequest:
            offset = (int(index) * int(HTR_WITHDRAWAL_REQUEST_LENGTH))
            if (int((int(offset) + int(HTR_WITHDRAWAL_REQUEST_LENGTH))) <= int(requests.len)):
                request = stateless_input_sub_slice(requests, offset, HTR_WITHDRAWAL_REQUEST_LENGTH)
                return Bytes32(htr_withdrawal_request(request))
            else:
                return Bytes32(fatal_error(FatalError.InvalidConfig))
        case HtrRequestKind.HtrConsolidationRequest:
            offset = (int(index) * int(HTR_CONSOLIDATION_REQUEST_LENGTH))
            if (int((int(offset) + int(HTR_CONSOLIDATION_REQUEST_LENGTH))) <= int(requests.len)):
                request = stateless_input_sub_slice(requests, offset, HTR_CONSOLIDATION_REQUEST_LENGTH)
                return Bytes32(htr_consolidation_request(request))
            else:
                return Bytes32(fatal_error(FatalError.InvalidConfig))
        case HtrRequestKind.HtrBuilderDepositRequest:
            offset = (int(index) * int(HTR_BUILDER_DEPOSIT_LENGTH))
            if (int((int(offset) + int(HTR_BUILDER_DEPOSIT_LENGTH))) <= int(requests.len)):
                request = stateless_input_sub_slice(requests, offset, HTR_BUILDER_DEPOSIT_LENGTH)
                return Bytes32(htr_builder_deposit_request(request))
            else:
                return Bytes32(fatal_error(FatalError.InvalidConfig))
        case HtrRequestKind.HtrBuilderExitRequest:
            offset = (int(index) * int(HTR_BUILDER_EXIT_LENGTH))
            if (int((int(offset) + int(HTR_BUILDER_EXIT_LENGTH))) <= int(requests.len)):
                request = stateless_input_sub_slice(requests, offset, HTR_BUILDER_EXIT_LENGTH)
                return Bytes32(htr_builder_exit_request(request))
            else:
                return Bytes32(fatal_error(FatalError.InvalidConfig))
        case _:
            raise SailMatchFailure("no Sail match clause applied")

def htr_requests_subtree(requests: StatelessInputSlice, kind: HtrRequestKind, start: int, count: htr_leaf_count, depth: htr_depth) -> hash:
    if ((count) == (0)):
        return Bytes32(ssz_zero_hash(depth))
    else:
        if ((depth) == (0)):
            if ((count) == (1)):
                return Bytes32(htr_request_leaf(requests, start, kind))
            else:
                return Bytes32(fatal_error(FatalError.WitnessDeficient))
        else:
            child_depth = (int(depth) - 1)
            half = htr_leaf_capacity(child_depth)
            if (int(count) < int(half)):
                left_count = count
            else:
                left_count = half
            if (int(count) < int(half)):
                right_count = 0
            else:
                right_count = (int(count) - int(half))
            left_root = htr_requests_subtree(requests, kind, start, left_count, child_depth)
            right_root = htr_requests_subtree(requests, kind, (int(start) + int(half)), right_count, child_depth)
            return Bytes32(_host_sha256_pair(left_root, right_root))

def htr_deposits(deposits: StatelessInputSlice) -> hash:
    items = ssz_bounded_fixed_list_ref(deposits, HTR_DEPOSIT_LENGTH, (1 << 13))
    count = items.count
    root = htr_requests_subtree(deposits, HtrRequestKind.HtrDeposit, 0, count, 13)
    return Bytes32(mix_in_length(root, items.count))

def htr_withdrawal_requests(requests: StatelessInputSlice) -> hash:
    items = ssz_bounded_fixed_list_ref(requests, HTR_WITHDRAWAL_REQUEST_LENGTH, (1 << 4))
    count = items.count
    root = htr_requests_subtree(requests, HtrRequestKind.HtrWithdrawalRequest, 0, count, 4)
    return Bytes32(mix_in_length(root, items.count))

def htr_consolidation_requests(requests: StatelessInputSlice) -> hash:
    items = ssz_bounded_fixed_list_ref(requests, HTR_CONSOLIDATION_REQUEST_LENGTH, (1 << 1))
    count = items.count
    root = htr_requests_subtree(requests, HtrRequestKind.HtrConsolidationRequest, 0, count, 1)
    return Bytes32(mix_in_length(root, items.count))

def htr_builder_deposit_requests(requests: StatelessInputSlice) -> hash:
    items = ssz_bounded_fixed_list_ref(requests, HTR_BUILDER_DEPOSIT_LENGTH, (1 << 6))
    count = items.count
    root = htr_requests_subtree(requests, HtrRequestKind.HtrBuilderDepositRequest, 0, count, 6)
    return Bytes32(mix_in_length(root, items.count))

def htr_builder_exit_requests(requests: StatelessInputSlice) -> hash:
    items = ssz_bounded_fixed_list_ref(requests, HTR_BUILDER_EXIT_LENGTH, (1 << 4))
    count = items.count
    root = htr_requests_subtree(requests, HtrRequestKind.HtrBuilderExitRequest, 0, count, 4)
    return Bytes32(mix_in_length(root, items.count))

def htr_execution_requests(input_ref: StatelessInputRef) -> hash:
    deposits = htr_deposits(input_ref.deposits)
    withdrawal_requests = htr_withdrawal_requests(input_ref.withdrawal_requests)
    consolidation_requests = htr_consolidation_requests(input_ref.consolidation_requests)
    builder_deposit_requests = htr_builder_deposit_requests(input_ref.builder_deposit_requests)
    builder_exit_requests = htr_builder_exit_requests(input_ref.builder_exit_requests)
    return Bytes32(merkleize([deposits, withdrawal_requests, consolidation_requests, builder_deposit_requests, builder_exit_requests], 3))

def htr_new_payload_request(input_ref: StatelessInputRef) -> hash:
    payload_root = htr_execution_payload(input_ref)
    versioned_hashes_root = htr_versioned_hashes(input_ref.versioned_hashes)
    beacon_root = htr_ssz_bytes32(input_ref.new_payload_request, NPR_BEACON_ROOT)
    requests_root = htr_execution_requests(input_ref)
    return Bytes32(merkleize([payload_root, versioned_hashes_root, beacon_root, requests_root], 2))

